<?php require __DIR__.'/bootstrap.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=$_POST['type']??''; if($type==='notice'){ $s=$pdo->prepare('INSERT INTO notices(title,body,author_id) VALUES(?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['body']),user()['id']]); } elseif($type==='event'){ $s=$pdo->prepare('INSERT INTO events(title,description,starts_at,ends_at,location,author_id) VALUES(?,?,?,?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['description']),$_POST['starts_at'],$_POST['ends_at']?:null,trim($_POST['location']),user()['id']]); } elseif($type==='timetable'){ $s=$pdo->prepare('INSERT INTO timetable_entries(user_id,day_of_week,starts_at,ends_at,subject,room) VALUES(?,?,?,?,?,?)');$s->execute([(int)$_POST['student_id'],(int)$_POST['day'],$_POST['starts_at'],$_POST['ends_at'],trim($_POST['subject']),trim($_POST['room'])]); } elseif($type==='feedback_status'){ $s=$pdo->prepare('UPDATE feedback SET status=? WHERE id=?');$s->execute([$_POST['status'],(int)$_POST['feedback_id']]); } log_action($pdo,'admin_'.$type);header('Location:admin.php');exit;}
$students=$pdo->query("SELECT id,name,email,course FROM users WHERE role='student' ORDER BY name")->fetchAll();$fb=$pdo->query('SELECT f.*,u.name FROM feedback f JOIN users u ON u.id=f.user_id ORDER BY f.created_at DESC LIMIT 20')->fetchAll();$logs=$pdo->query('SELECT l.*,u.name FROM audit_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 12')->fetchAll(); page_top('Administration'); ?>
<h1>Administration</h1><section class="grid two"><form class="panel form-grid" method="post"><h2>Publish notice</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="notice"><label class="full">Title<input required name="title"></label><label class="full">Message<textarea required name="body"></textarea></label><button>Publish</button></form><form class="panel form-grid" method="post"><h2>Add event</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="event"><label>Title<input required name="title"></label><label>Location<input name="location"></label><label>Starts<input required type="datetime-local" name="starts_at"></label><label>Ends<input type="datetime-local" name="ends_at"></label><label class="full">Description<textarea name="description"></textarea></label><button>Add event</button></form></section>
<section class="grid two"><form class="panel form-grid" method="post"><h2>Assign timetable entry</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="timetable"><label class="full">Student<select name="student_id"><?php foreach($students as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> - <?=e($x['course'])?></option><?php endforeach;?></select></label><label>Day<select name="day"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $i=>$d):?><option value="<?=$i+1?>"><?=$d?></option><?php endforeach;?></select></label><label>Subject<input required name="subject"></label><label>Start<input required type="time" name="starts_at"></label><label>End<input required type="time" name="ends_at"></label><label>Room<input name="room"></label><button>Save class</button></form><div class="panel"><h2>Students</h2><?php foreach($students as $x):?><p><b><?=e($x['name'])?></b><br><small><?=e($x['email'])?> · <?=e($x['course'])?></small></p><?php endforeach;?></div></section>
<section class="panel"><h2>Feedback queue</h2><?php foreach($fb as $f):?><article class="item"><b><?=e($f['name'])?>: <?=e($f['subject'])?></b><p><?=e($f['message'])?></p><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="feedback_status"><input type="hidden" name="feedback_id" value="<?=$f['id']?>"><select name="status"><?php foreach(['open','reviewed','closed'] as $status):?><option <?=$status===$f['status']?'selected':''?>><?=$status?></option><?php endforeach;?></select><button class="secondary">Update</button></form></article><?php endforeach;?></section><section class="panel"><h2>Recent activity</h2><?php foreach($logs as $l):?><p><small><?=date('d M H:i',strtotime($l['created_at']))?> - <?=e($l['name']??'System')?>: <?=e($l['action'])?> <?=e($l['detail'])?></small></p><?php endforeach;?></section><?php page_bottom();
